		if (order == null) {
			return null;
		}
		long subj = PatternPlan.lookupUnbinding(pattern.s, row.slots, keyMask);
		long pred = PatternPlan.lookupUnbinding(pattern.p, row.slots, keyMask);
		long obj = PatternPlan.lookupUnbinding(pattern.o, row.slots, keyMask);
		long ctx = PatternPlan.lookupUnbinding(pattern.c, row.slots, keyMask);
		String indexName = row.source.indexName(order, subj, pred, obj, ctx);
